// Wraps each tokos/drill/<id>.json into tokos-models/drill-<id>.js (ES5 UMD) so the buildless engine
// gets {id, kind, ..., stages, score} from one script. The JSON stays the reviewable source (Review Desk,
// apply-reviews). Run after editing any drill JSON: node tools/tokos-build-drills.mjs
// test/tokos-drill-core.test.mjs fails if a generated file is stale. Never shipped (tools/ is 404 on the web).
// --host narke builds narke/drill/<id>.json into narke-models/ (NARKE_MODELS) and copies the shared scorer
// tokos-models/drill-core.js to narke-models/drill-core.js (test/narke-drills.test.mjs keeps the copy identical).
import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync, copyFileSync } from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const core = require("../tokos-models/drill-core.js");
const ROOT = new URL("..", import.meta.url).pathname;

export function render(data, host = "tokos") {
  const G = host.toUpperCase() + "_MODELS";
  return `/* Generated by tools/tokos-build-drills.mjs from ${host}/drill/${data.id}.json. Edit the JSON, not this file. */
(function (G) {
  "use strict";
  var node = typeof module !== "undefined" && module.exports;
  var core = node ? require("./drill-core.js") : G.TOKOS_DRILL_CORE;
  var model = core.make(${JSON.stringify(data)});
  if (node) module.exports = model;
  else (G.${G} = G.${G} || {})[model.id] = model;
})(typeof window !== "undefined" ? window : this);
`;
}

export function drillIds(host = "tokos") {
  if (!existsSync(ROOT + host + "/drill")) return [];
  return readdirSync(ROOT + host + "/drill").filter((f) => f.endsWith(".json")).map((f) => f.slice(0, -5)).sort();
}

if (import.meta.url === `file://${process.argv[1]}`) {
  let bad = 0;
  const hi = process.argv.indexOf("--host"), host = hi > 0 ? process.argv[hi + 1] : "tokos";
  if (!/^(tokos|narke)$/.test(host)) { console.error("unknown host " + host); process.exit(2); }
  if (host !== "tokos") { mkdirSync(ROOT + host + "-models", { recursive: true }); copyFileSync(ROOT + "tokos-models/drill-core.js", ROOT + host + "-models/drill-core.js"); }
  for (const id of drillIds(host)) {
    const data = JSON.parse(readFileSync(`${ROOT}${host}/drill/${id}.json`, "utf8"));
    const errs = core.validate(data);
    if (errs.length) { bad++; console.error(id, errs); continue; }
    writeFileSync(`${ROOT}${host}-models/drill-${id}.js`, render(data, host));
    console.log("wrote " + host + "-models/drill-" + id + ".js");
  }
  process.exit(bad ? 1 : 0);
}
